  const norm = (s) => s.replace(/\s+/g, ' ').trim();
  const t = (s) => (lang === 'en' && TEXT[norm(s)]) || s;
  window.I18N = { lang, t };

  /* ---------- Dil düğmesi (menüye eklenir) ---------- */
  function addToggle() {
    const nav = document.querySelector('header.nav, header.snav');
    if (!nav || nav.querySelector('.dil-btn')) return;
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'dil-btn';
    b.lang = lang === 'en' ? 'tr' : 'en';
    b.innerHTML = lang === 'en' ? '<span aria-hidden="true">TR</span>' : '<span aria-hidden="true">EN</span>';
    b.setAttribute('aria-label', lang === 'en' ? 'Türkçeye geç' : 'Switch to English');
    b.addEventListener('click', () => {
      try { localStorage.setItem(KEY, lang === 'en' ? 'tr' : 'en'); } catch (e) { return; }
      location.reload();
    });
    const ext = nav.querySelector('.nav__ext');
    if (ext) nav.insertBefore(b, ext); else nav.appendChild(b);
    const st = document.createElement('style');
    st.textContent = `
      .dil-btn { position: relative; z-index: 2; flex: none; font: 600 12px/1 'JetBrains Mono', monospace; letter-spacing: .08em; color: #B8A58A;
        border: 1px solid rgba(184,165,138,.45); border-radius: 999px; padding: 8px 12px; min-height: 36px; margin-left: 12px; background: transparent; cursor: pointer;
        transition: background-color .3s, border-color .3s; }
      .dil-btn:hover { background: #8A6845; border-color: #8A6845; }
      header.nav .dil-btn { margin-left: auto; margin-right: 14px; }
      @media (max-width: 860px) { header.snav .dil-btn { order: 2; } header.snav .snav__links { order: 3; } }
      @media (max-width: 768px) { header.nav .dil-btn { margin-right: 8px; padding: 8px 11px; min-height: 38px; } }`;
    document.head.appendChild(st);
  }
  addToggle();
  if (lang !== 'en') return;

  /* ---------- İngilizce ---------- */
  document.documentElement.lang = 'en';

  // Ana sayfa verisi (projeler, yazılar, kayan şeritler)
  const D = window.DATA;
  if (D) {
    if (D.skills) Object.assign(D.skills, DATA_EN.skills);
    (D.posts || []).forEach((p) => Object.assign(p, DATA_EN.posts[p.slug] || {}));
    (D.projects || []).forEach((p) => Object.assign(p, DATA_EN.projects[p.slug] || {}));
  }

  // Başlık ve açıklamalar
  if (META[norm(document.title)]) document.title = META[norm(document.title)];
  document.querySelectorAll('meta[name="description"], meta[property="og:title"], meta[property="og:description"]').forEach((m) => {
    const v = META[norm(m.content)]; if (v) m.content = v;
  });
  const og = document.querySelector('meta[property="og:locale"]'); if (og) og.content = 'en_US';

  const SKIP = new Set(['SCRIPT', 'STYLE', 'PRE', 'TEXTAREA', 'svg']);
  function textNode(n) {
    const raw = n.nodeValue, v = norm(raw);
    if (!v) return;
    let out = TEXT[v];
    if (!out && /Öğr\. Gör\.|Sanal sınıf/.test(v)) { out = v; SUBS.forEach(([a, b]) => { out = out.split(a).join(b); }); }
    if (out && out !== v) n.nodeValue = raw.match(/^\s*/)[0] + out + raw.match(/\s*$/)[0];
  }
  function attrs(el) {
    for (const a of ['alt', 'aria-label', 'title', 'placeholder']) {
      const v = el.getAttribute && el.getAttribute(a);
      if (v && ATTR[norm(v)]) el.setAttribute(a, ATTR[norm(v)]);
    }
  }
  function translate(root) {
    if (root.nodeType === 3) { if (!root.parentElement || !root.parentElement.closest('pre, script, style')) textNode(root); return; }
    if (root.nodeType !== 1 || SKIP.has(root.nodeName) || root.closest('pre')) return;
    // 1) Satır içi etiket (abbr, code, strong) içeren birkaç paragraf: bütünüyle
    root.querySelectorAll('p').forEach((p) => { const h = BLOCK[norm(p.textContent)]; if (h) p.innerHTML = h; });
    // 2) Metin düğümleri
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode: (n) => (n.parentElement && n.parentElement.closest('pre, script, style, textarea') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT)
    });
    for (let n = w.nextNode(); n; n = w.nextNode()) textNode(n);
    // 3) Öznitelikler
    attrs(root);
    root.querySelectorAll('[alt], [aria-label], [title], [placeholder]').forEach(attrs);
  }
  translate(document.body);

  // Sonradan eklenen / değişen içerik
  new MutationObserver((list) => {
    for (const m of list) {
      if (m.type === 'childList') m.addedNodes.forEach(translate);
      else if (m.type === 'attributes') attrs(m.target);
    }
  }).observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['title', 'aria-label', 'alt'] });
